    ((select id from public.chapters where subject_id = 'histoire' and title = 'Les cinq grandes périodes de l''Histoire'), 'ordre', 'Range les événements, du plus ancien au plus récent.', 'ordre', array['Apparition de l''écriture|-3 300','Chute de l''Empire romain|476','Découverte de l''Amérique|1492','Révolution française|1789']::text[], null),
    ((select id from public.chapters where subject_id = 'histoire' and title = 'Les cinq grandes périodes de l''Histoire'), 'ordre', 'Range les dates, de la plus ancienne à la plus récente.', 'ordre', array['-3 300|apparition de l''écriture','476|chute de l''Empire romain','1492|découverte de l''Amérique','1789|Révolution française']::text[], 'Une date avec un signe moins est avant l''année 0 : -3 300 est la plus ancienne.'),
    ((select id from public.chapters where subject_id = 'histoire' and title = 'Les premiers hommes'), 'ordre', 'Range les premiers hommes, du plus ancien au plus récent.', 'ordre', array['Australopithèque|-4,5 millions d''années','Homo habilis|-2,4 millions d''années','Homo erectus|-1,9 million d''années','Homme de Neandertal|-350 000 ans','Homo sapiens|-200 000 ans']::text[], null),
    ((select id from public.chapters where subject_id = 'histoire' and title = 'Les premiers hommes'), 'ordre', 'Range ces premières fois dans l''ordre où elles sont apparues.', 'ordre', array['Se déplacer debout|Australopithèque','Se servir d''outils|Homo habilis','Faire du feu|Homo erectus','Enterrer ses morts|homme de Neandertal','Créer des œuvres d''art|Homo sapiens']::text[], null),
    ((select id from public.chapters where subject_id = 'histoire' and title = 'La Préhistoire : vestiges et art'), 'ordre', 'Range ces vestiges, du plus ancien au plus récent.', 'ordre', array['Dent humaine|550 000 ans','Pointe de lance en silex|19 000 ans','Tombe de deux femmes|7 000 ans','Hache en pierre et bois de cerf|5 000 ans']::text[], 'Plus le nombre d''années est grand, plus le vestige est ancien.');
